#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    
    vector<int> arr(n);
    for (int i = 0; i < n; i++) cin >> arr[i];
    
    vector<char> ans;
    vector<int> stack;
    int cnt = 0;
    
    for (int i = 1; i <= n; i++) {
        stack.push_back(i);
        ans.push_back('+');
        
        while (!stack.empty() && stack.back() == arr[cnt]) {
            stack.pop_back();
            ans.push_back('-');
            cnt++;
        }
    }
    
    if (!stack.empty()) {
        cout << "NO";
    } else {
        for (char c : ans) {
            cout << c << '\n';
        }
    }
    
    return 0;
}

